# Initially generated by GitHub Copilot.
"""Bot edit: migrate issue-67 deprecated כו"ק call sites to מ:כו"ק מיוחד.

Rewrite rule per call site:
  1. Keep positional parameters unchanged.
  2. Replace template name with מ:כו"ק מיוחד.
  3. Add סוג=<old-template-name-without-leading-"מ:">.
  4. Preserve remaining parameters.

Safety rule:
  - Hard preflight for רווח=כן on deprecated template calls.
  - If found, stop with SystemExit for manual handling.
"""

from functools import partial

from mb_cmn import hebrew_verse_numerals as hvn
from mb_cmn import template_names as tmpln
from mb_cmn import ws_tmpl1 as wtp1
from mb_cmn import ws_tmpl2 as wtp
from mb_cmn.my_utils import dv_dispatch
from mb_cmn.my_utils import dkv_map
from mb_cmn.my_utils import sl_map
from mb_cmn.my_utils import sum_of_map
from mb_cmn.shrink import shrink
from ws import ws_fmt_2_back_to_wikitext as btw
from ws import ws_get_bk_in_both_fmts as wsin
from ws import ws_unparse

_ctx = {
    "bk39id": None,
    "he_chnu": None,
    "chapter": None,
    "he_vrnu": None,
    "verse": None,
}
_warnings = []

_NEW_TMPL_NAME = 'מ:כו"ק מיוחד'

_DEPRECATED_TMPL_NAMES = (
    tmpln.K1Q1_MCOM,
    tmpln.K1Q2_SR_BCOM,
    tmpln.K3Q3,
    tmpln.K1Q2_SR_QQK,
    tmpln.K1Q2_WR_KQQ,
    tmpln.K1Q2_UR_QQK,
    tmpln.K2Q1,
    tmpln.K2Q2,
    tmpln.K1Q2_SR_KQQ,
)


def get_warnings():
    return list(_warnings)


def _warn(reason, tmpl):
    _warnings.append(
        {
            "bk39id": _ctx["bk39id"],
            "he_chnu": _ctx["he_chnu"],
            "chapter": _ctx["chapter"],
            "he_vrnu": _ctx["he_vrnu"],
            "verse": _ctx["verse"],
            "reason": reason,
            "old_tmpl_text": ws_unparse.unparse(tmpl),
        }
    )


def _sug_text_for_old_template_name(old_name):
    assert old_name.startswith("מ:"), old_name
    return old_name[2:]


def _is_rvach_yes(tmpl):
    tmpl2 = wtp.use_tmpl2(tmpl)
    if "רווח" not in wtp.template_param_keys(tmpl2):
        return False
    rvach_val = wtp.template_param_val(tmpl2, "רווח")
    return (
        len(rvach_val) == 1 and isinstance(rvach_val[0], str) and rvach_val[0] == "כן"
    )


def _collect_rvach_yes_warnings_in_wtseq(wtseq):
    for wtel in wtseq:
        if isinstance(wtel, str):
            continue
        if wtp1.is_abtag(wtel):
            continue
        tmpl_name = wtp1.template_name(wtel)
        if tmpl_name in _DEPRECATED_TMPL_NAMES and _is_rvach_yes(wtel):
            _warn("rvach-yes-manual-review", wtel)
        for arg in wtp1.template_arguments(wtel):
            _collect_rvach_yes_warnings_in_wtseq(arg)


def _assert_preflight_passes(cif2):
    chap_body = cif2["ws-chap-body"]
    for he_vrnu, plb_verse in chap_body.items():
        _ctx["he_vrnu"] = he_vrnu
        _ctx["verse"] = hvn.STR_TO_INT_DIC[he_vrnu]
        _collect_rvach_yes_warnings_in_wtseq(plb_verse["verse-body"])
    if not _warnings:
        return
    first = _warnings[0]
    chapter = first["chapter"]
    verse = first["verse"]
    old_tmpl_text = first["old_tmpl_text"]
    raise SystemExit(
        "Found deprecated template call(s) with רווח=כן. "
        "Stop for manual decision before migration. "
        f"Count={len(_warnings)}. "
        f"First occurrence: {_ctx['bk39id']} {chapter}:{verse} {old_tmpl_text}"
    )


def _transform_kuk_special_callsite(tmpl):
    old_name = wtp1.template_name(tmpl)
    assert old_name in _DEPRECATED_TMPL_NAMES, old_name
    assert not _is_rvach_yes(tmpl), "preflight should block רווח=כן"

    old_els = wtp1.template_elements(tmpl)
    tmpl2 = wtp.use_tmpl2(tmpl)
    sug_text = _sug_text_for_old_template_name(old_name)

    new_els = [[_NEW_TMPL_NAME], *old_els[1:]]
    if "סוג" in wtp.template_param_keys(tmpl2):
        existing_sug = wtp.template_param_val(tmpl2, "סוג")
        assert existing_sug == [sug_text], (old_name, existing_sug, sug_text)
    else:
        new_els.append([f"סוג={sug_text}"])

    return [wtp1.mktmpl(new_els)]


def _pass_thru(val):
    return val


def _pass_thru_as_singleton(val):
    return [val]


def _edit_wtseq(wandlers, wtseq):
    return shrink(sum_of_map((_edit_wtel, wandlers), wtseq))


def _edit_wtel(wandlers, wtel):
    if isinstance(wtel, str):
        return wandlers["string"](wtel)
    if wtp1.is_abtag(wtel):
        return [wtel]
    return _edit_tmpl_call(wandlers, wtel)


def _edit_tmpl_call(wandlers, tmpl):
    if wandler := wandlers.get(wtp1.template_name(tmpl)):
        return wandler(tmpl)
    return _recurse_on_args(_get_wandlers, tmpl)


def _recurse_on_args(get_wandlers_fn, tmpl):
    tmpl_els_in = wtp1.template_elements(tmpl)
    assert isinstance(tmpl_els_in, list)
    wandlers = get_wandlers_fn()
    tmpl_args_out = sl_map((_edit_wtseq, wandlers), tmpl_els_in[1:])
    tmpl_els_out = [tmpl_els_in[0], *tmpl_args_out]
    return [wtp1.mktmpl(tmpl_els_out)]


def _get_wandlers():
    return _WANDLERS


def _edit_a_chap_body(vandlers, chap_body):
    return dkv_map((_edit_a_plb_verse, vandlers), chap_body)


def _edit_a_plb_verse(vandlers, he_vrnu, plb_verse):
    _ctx["he_vrnu"] = he_vrnu
    _ctx["verse"] = hvn.STR_TO_INT_DIC[he_vrnu]
    return dv_dispatch(vandlers, plb_verse)


_WANDLERS = {
    "string": _pass_thru_as_singleton,
    **{name: _transform_kuk_special_callsite for name in _DEPRECATED_TMPL_NAMES},
}

_VANDLERS = {
    "prefix": _pass_thru,
    "location": _pass_thru,
    "verse-body": partial(_edit_wtseq, _WANDLERS),
}

_CANDLERS = {
    "ws-chap-noinclude-header": _pass_thru,
    "ws-chap-body": partial(_edit_a_chap_body, _VANDLERS),
    "ws-chap-good-ending": _pass_thru,
    "ws-chap-noinclude-footer": _pass_thru,
    "ws-chap-category": _pass_thru,
}


def edit_cif2(he_chnu, cif2):
    out_cif2 = dv_dispatch(_CANDLERS, cif2)
    return out_cif2, btw.big_str(he_chnu, out_cif2)


def edit_page_text(bk39id, he_chnu, page_text):
    _warnings.clear()
    _ctx["bk39id"] = bk39id
    _ctx["he_chnu"] = he_chnu
    _ctx["chapter"] = hvn.STR_TO_INT_DIC[he_chnu]

    cif2 = wsin.get_chap_in_fmt_2(page_text.splitlines())
    _assert_preflight_passes(cif2)
    _out_cif2, big_str = edit_cif2(he_chnu, cif2)
    return big_str
